from __future__ import unicode_literals

from typing import Tuple, List

from cfnlint._typing import RuleMatches
from cfnlint.rules import CloudFormationLintRule, RuleMatch
from cfnlint.template import Template
from cfnlint.decode import cfn_yaml


class Used(CloudFormationLintRule):
    """Check if Parameters are used"""

    id = "W2001"
    shortdesc = "Check if Parameters are Used"
    description = "Making sure the parameters defined are used"
    source_url = "https://github.com/aws-cloudformation/cfn-lint"
    tags = ["parameters"]

    def _gather_refs_from_include(self, cfn: Template) -> Tuple[List[str], List[str]]:
        """Scan Fn::Transform blocks for AWS::Include and gather parameter references.

        Only local file locations are processed. Remote includes (s3/http/https) are skipped.
        """
        include_refs: List[str] = []
        include_sub_params: List[str] = []

        try:
            transform_fns = cfn.search_deep_keys("Fn::Transform")
        except Exception:
            transform_fns = []

        for tf in transform_fns:
            spec = tf[-1]
            if not isinstance(spec, dict):
                continue
            name = spec.get("Name")
            if name != "AWS::Include":
                continue
            params = spec.get("Parameters", {})
            location = params.get("Location") if isinstance(params, dict) else None
            if not isinstance(location, str):
                continue
            loc_lower = location.lower()
            if (
                loc_lower.startswith("s3://")
                or loc_lower.startswith("http://")
                or loc_lower.startswith("https://")
            ):
                # Skip remote includes
                continue
            try:
                included = cfn_yaml.load(location)
            except Exception:
                # If we can't load the include, ignore it silently
                continue
            try:
                temp_cfn = Template(None, included)
            except Exception:
                temp_cfn = None
            if not temp_cfn:
                continue

            # Gather Refs from the included content (only string ref values)
            try:
                for reftree in temp_cfn.search_deep_keys("Ref"):
                    if isinstance(reftree[-1], str):
                        include_refs.append(reftree[-1])
            except Exception:
                pass

            # Gather Fn::Sub parameters from included content
            try:
                for subtree in temp_cfn.search_deep_keys("Fn::Sub"):
                    if isinstance(subtree[-1], list):
                        include_sub_params.extend(
                            temp_cfn.get_sub_parameters(subtree[-1][0])
                        )
                    elif isinstance(subtree[-1], str):
                        include_sub_params.extend(temp_cfn.get_sub_parameters(subtree[-1]))
            except Exception:
                pass

        return include_refs, include_sub_params

    def match(self, cfn: Template) -> RuleMatches:
        matches: RuleMatches = []

        le_refs = None
        if cfn.has_language_extensions_transform():
            le_refs = cfn.search_deep_keys("Ref")

        reftrees = cfn.transform_pre.get("Ref", [])
        subtrees = cfn.transform_pre.get("Fn::Sub", [])
        refs: List[str] = []
        for reftree in reftrees:
            # Only add string values to refs
            if isinstance(reftree[-1], str):
                refs.append(reftree[-1])
        if le_refs:
            for le_ref in le_refs:
                if isinstance(le_ref[-1], str):
                    if le_ref[-1] not in refs:
                        refs.append(le_ref[-1])

        subs: List[str] = []
        for subtree in subtrees:
            if isinstance(subtree[-1], list):
                subs.extend(cfn.get_sub_parameters(subtree[-1][0]))
            elif isinstance(subtree[-1], str):
                subs.extend(cfn.get_sub_parameters(subtree[-1]))

        # Merge in references found within locally included content
        include_refs, include_subs = self._gather_refs_from_include(cfn)
        for v in include_refs:
            if isinstance(v, str) and v not in refs:
                refs.append(v)
        for v in include_subs:
            if isinstance(v, str) and v not in subs:
                subs.append(v)

        for paramname in cfn.template.get("Parameters", {}).keys():
            if paramname not in refs and paramname not in subs:
                message = "Parameter {0} not used."
                matches.append(
                    RuleMatch(["Parameters", paramname], message.format(paramname))
                )

        return matches

